<script setup lang="ts">
import {onMounted,ref} from 'vue';import {api} from '../state';
const emit=defineEmits<{select:[string];close:[]}>();const path=ref(''),parent=ref(''),entries=ref<{name:string;path:string}[]>([]),busy=ref(false),error=ref(''),q=ref(''),truncated=ref(false);let generation=0;
async function load(p=''){const g=++generation;busy.value=true;error.value='';try{const data=await api.get<any>('/library-folders?'+new URLSearchParams({path:p,q:q.value}));if(g!==generation)return;path.value=data.path;parent.value=data.parent;entries.value=data.entries;truncated.value=data.truncated}catch(e:any){if(g===generation)error.value=e.message}finally{if(g===generation)busy.value=false}}
onMounted(()=>load());
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="sheet folder-picker" role="dialog" aria-modal="true" aria-label="选择漫画目录"><button class="close" @click="emit('close')">关闭</button><h2>选择漫画目录</h2><p>选择已挂载到 nasReader 的目录，原文件保持只读。</p><div class="folder-path"><button :disabled="!parent||busy" @click="q='';load(parent)">上一级</button><span>{{path||'正在读取…'}}</span></div><form @submit.prevent="load(path)"><input v-model="q" aria-label="搜索文件夹" placeholder="搜索当前目录下的文件夹"><button>搜索</button></form><p v-if="busy" role="status">正在读取目录…</p><p v-else-if="error" role="alert">{{error}} <button @click="load(path)">重试</button></p><div v-else class="folders"><button v-for="entry in entries" :key="entry.path" @click="q='';load(entry.path)"><span aria-hidden="true">▱</span>{{entry.name}}<span aria-hidden="true">›</span></button><p v-if="!entries.length">此目录下没有可浏览的子文件夹。</p><p v-if="truncated">文件夹较多，请输入名称搜索。</p></div><div class="folder-actions"><button @click="emit('close')">取消</button><button class="primary" :disabled="busy||!path||!!error" @click="emit('select',path)">选择此目录</button></div></section></div></template>
<style scoped>
.folder-picker{max-width:640px;width:calc(100% - 32px);padding:24px}.folder-path{display:flex;align-items:center;gap:10px;margin:12px 0}.folder-path span{font-size:13px;overflow-wrap:anywhere}.folder-picker form{display:flex;gap:8px}.folder-picker form input{min-width:0;margin:0}.folder-picker form button{margin:0}.folders{max-height:320px;overflow:auto;margin:16px 0}.folders>button{display:flex;gap:12px;align-items:center;border:0;border-bottom:1px solid var(--border);border-radius:0;width:100%;min-height:44px;text-align:left}.folders>button>span:last-child{margin-left:auto}.folder-actions{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid var(--border);padding-top:16px}
</style>
